/**
 * A plan as a card: name, tagline, price per month, the features, a call to action and an optional slot for more
 * actions. Text comes in through `labels`; the plan is data.
 */
import { type ReactNode } from "react";
import { Badge, Block, Box, Button, CardContent, CardDescription, CardFooter, CardHeader, CardTitle, Group, List, ListItem, Text, Title } from "../compose";
import { cn, fmtMoney, tpl } from "../utils";
import type { Plan, PricingCardLabels } from "./pricing-card.types";

export type PricingCardProps = {
  plan: Plan;
  labels: PricingCardLabels;
  current?: boolean;
  emphasis?: "auto" | "off";
  density?: "default" | "compact";
  billing?: "monthly" | "annual";
  footer?: (plan: Plan) => ReactNode;
  onSelect?: (id: string) => void;
};

export function PricingCard({
  plan,
  labels,
  current,
  emphasis = "auto",
  density = "default",
  billing = "monthly",
  footer,
  onSelect,
}: PricingCardProps) {
  const stand = plan.highlighted && ((emphasis as string) === "auto");
  const yearlyOn = ((billing as string) === "annual") && (plan.yearly > 0);
  const amount = yearlyOn ? plan.yearly : plan.price;
  return (
    <Block
      tag="article"
      className={cn(
        "flex flex-col gap-8 bg-card p-6 text-card-foreground inset-ring inset-ring-border rounded",
        "flex h-full flex-col"
      )}
      data-slot="card"
      data-highlighted={(stand ? "true" : "false")}
      data-current={(current ? "true" : "false")}
    >
      <CardHeader className="flex flex-col gap-2">
        <Box className="flex min-h-6 items-center" data-slot="badge-slot">
          {stand ? (
            <Badge variant="default" size="default">
              {labels.popular}
            </Badge>
          ) : null}
        </Box>
        <CardTitle as={3}>
          {plan.name}
        </CardTitle>
        <CardDescription>
          {plan.tagline}
        </CardDescription>
      </CardHeader>
      <CardContent className={cn("flex flex-1 flex-col", (((density as string) === "compact") ? "gap-2" : "gap-4"))}>
        <Group gap="2" align="baseline">
          <Title as={2} size="4xl" weight="bold">
            {(amount === 0) ? (
              <>
                {labels.free}
              </>
            ) : (
              <>
                {fmtMoney(amount, plan.currency)}
              </>
            )}
          </Title>
          {(amount > 0) ? (
            <Text size="sm" className="text-muted-foreground">
              {(yearlyOn ? labels.perYear : labels.perMonth)}
            </Text>
          ) : null}
        </Group>
        <Text size="sm" weight="medium">
          {tpl(labels.seats, plan.seats)}
        </Text>
        <Text size="sm" className="text-muted-foreground">
          {tpl(labels.storage, plan.storage)}
        </Text>
        <List tag="ul" className="flex flex-col gap-2 text-sm">
          {(plan.features ?? []).map((feature) => (
            <ListItem key={feature} className="flex gap-2">
              {feature}
            </ListItem>
          ))}
        </List>
      </CardContent>
      <CardFooter className="flex flex-wrap items-center gap-2">
        <Button
          variant={(stand ? "default" : "outline")}
          size="default"
          data-testid="plan-select"
          onClick={() => onSelect?.(plan.id)}
        >
          {labels.cta}
        </Button>
        {footer?.(plan)}
      </CardFooter>
    </Block>
  );
}

// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.

export type Plan = {
  id: string;
  name: string;
  tagline: string;
  price: number;
  currency: string;
  seats: number;
  storage: number;
  highlighted: boolean;
  status?: string;
  features: string[];
  yearly: number;
};

export type PricingCardLabels = {
  popular: string;
  perMonth: string;
  seats: string;
  storage: string;
  cta: string;
  free: string;
  perYear: string;
  empty: string;
};
